contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount >= 0);
        require(address(this).balance >= amount);

        uint beforePot = c.pot();
        uint beforeCBalance = address(c).balance;
        uint beforeBankBalance = c.bank().balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.pot() == beforePot && address(c).balance == beforeCBalance);
        } else {
            assert(amount == 10);
            assert(address(c).balance == beforeCBalance + (c.pot() == 0 ? 0 : amount));
            assert(c.pot() == 0 || c.pot() == beforePot + amount);
        }
    }

    receive() external payable {}
}

