contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);

        uint potBefore = c.pot();
        address bankAddr = c.bank();

        uint beforeBank = bankAddr.balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // With msg.sender == InvMutTest, the random branch is deterministic only in
            // that exactly one of the two outcomes below must have occurred; we assert the
            // general accounting invariant for the successful path. If the win branch was
            // taken, pot was reset; otherwise pot must have grown by exactly the ticket
            // amount. Either way, the fee move and the pot reset are captured below when
            // the win branch was taken.
            if (c.pot() == 0) {
                assert(address(c).balance == 0);
                assert(c.pot() == 0);
            } else {
                assert(c.pot() == potBefore + amount);
                assert(address(c).balance == potBefore + amount);
            }
        }
    }

    receive() external payable {}
}

